"""Seed the Heritage section (tangible / intangible / world heritage) with
representative, factual Indian cultural records.

Non-destructive: already-seeded sites are left untouched, so this can be re-run
against the official dataset later without losing data. UNESCO statuses/years
are real; where authority is unclear, text is kept generic so nothing is
fabricated. ``google_360_url`` stores a Google-integrated Street View / 360°
link per site and can be updated at any time.
"""
import datetime

from .database import Base, SessionLocal, engine
from .models import HeritageCategory, HeritageImage, HeritageSite


def streetview(lat: float, lon: float) -> str:
    """Google Street View / 360° integration URL for a site's coordinates."""
    return f"https://www.google.com/maps?layer=c&cbll={lat},{lon}&cbp=11,0,0,0,0"


def wm(path: str, width: int = 900) -> str:
    """Wikimedia Commons image URL (redirects to the file thumb)."""
    return f"https://commons.wikimedia.org/wiki/Special:FilePath/{path}?width={width}"


